@Path("unregister-node") @POST @Produces(MediaType.APPLICATION_JSON) public Response unregisterNode(@HeaderParam(HttpHeaders.AUTHORIZATION) String authorizationHeader, final MultivaluedMap<String, String> formData) {
  if (!checkSsl()) {
    throw new ForbiddenException("HTTPS required");
  }
  try {
    event.event(EventType.UNREGISTER_NODE);
    if (!realm.isEnabled()) {
      event.error(Errors.REALM_DISABLED);
      throw new UnauthorizedException("Realm not enabled");
    }
    ClientModel client = authorizeClient();
    String nodeHost = getClientClusterHost(formData);
    event.client(client).detail(Details.NODE_HOST, nodeHost);
    logger.debugf("Unregistering cluster host '%s' for client '%s'", nodeHost, client.getClientId());
    client.unregisterNode(nodeHost);
    event.success();
    return Response.noContent().build();
  } catch (NullPointerException | IllegalArgumentException | ClassCastException | BadRequestException | AuthenticationFlowException | IllegalStateException e) {
    logger.error("Error unregistering node: ", e);
    return Response.status(Response.Status.INTERNAL_SERVER_ERROR).build();
  }
}
